Function par <- ParJson(nombre As String, stock As Integer)
  Define par As String;
  par <- '"' + nombre + '": ' + toText(stock);
EndFunction

Algorithm DosPares
  Define primero As String;
  Define primerStock As Integer;
  Define segundo As String;
  Define segundoStock As Integer;
  Read primero;
  Read primerStock;
  Read segundo;
  Read segundoStock;
  Write "{", ParJson(primero, primerStock), ", ", ParJson(segundo, segundoStock), "}";
EndAlgorithm
